export default function next({ values, previous }) {
  if (!Array.isArray(values)) throw Error("Missing URLs");
  const index = previous?.index ?? 0;
  if (!Number.isInteger(index) || index < 0 || index > values.length)
    throw Error("Invalid URL cursor");
  if (index === values.length) return { state: { index }, more: false, url: "" };
  const url = String(values[index]?.[0] ?? "").trim();
  if (!/^https?:\/\//i.test(url)) throw Error("A URL row is empty or invalid");
  return { state: { index: index + 1 }, more: true, url };
}

