export default function rows({ body, url }) {
  const items = body?.output;
  if (!Array.isArray(items)) throw Error("Vision relay did not return an array");
  const values = items.map((p) => {
    if (!p || typeof p !== "object" || typeof p.product_title !== "string")
      throw Error("Invalid product");
    return [
      url,
      p.product_title,
      String(p.product_price ?? ""),
      String(p.product_brand ?? ""),
      String(p.promo ?? ""),
      String(p.promo_percentage ?? p.promo_percent ?? ""),
    ];
  });
  return { values, hasRows: values.length > 0 };
}

